                                      "quote": "제2조 제3항 (수술에서 제외하는 사항)\n다음 각 호의 처치나 조작은 이 특약에서 정한 '수술'의 정의에서 제외하므로 보험금을 지급하지 아니합니다.\n1. 흡인(吸引, 바늘이나 카테터로 체액이나 고름을 빨아들이는 것)\n2. 천자(穿刺, 바늘이나 카테터로 찔러서 조직이나 액체를 뽑아내는 것)\n3. 신경차단(Nerve Block) 및 국소마취하 통증 유발점 주사치료\n4. 미용성형 목적의 수술(쌍꺼풀, 외모 개선 안면거상, 융비술, 지방흡입 등)\n5. 피임 목적의 수술, 불임검사, 인공수정 및 체외수정 관련 시술\n\n제4조(보험금을 지급하지 않는 사유)\n1. 피보험자, 보험수익자 또는 계약자의 고의 또는 자해\n2. 정상분만(자연분만), 치과 질환(치주질환 및 치아보철 목적 처치 K00~K08)\n3. 선천성 기형 및 변형(Q코드, 단 선천이상특약 별도가입 시 예외)\n4. 한의원 또는 한방병원에서의 침, 뜸, 부항, 한방 시술",
