                                      "quote": "제1조(보험금의 지급사유)\n회사는 피보험자가 이 특약의 보험기간 중 질병의 치료를 직접적인 목적으로 병원 또는 의원(한방병원 또는 한의원 제외) 등에 입원 또는 통원하여 의사의 관리 하에 수술을 받은 때에는 매 수술 1회당 계약시 약정한 간편 질병수술급여금을 지급합니다.\n\n제2조(수술의 정의와 장소)\n① 이 특약에서 '수술'이라 함은 의사에 의하여 질병의 치료가 필요하다고 인정된 경우로서 자택 등에서의 치료가 곤란하여 의료법 제3조에서 정한 국내의 병원이나 의원 또는 국외의 의료관련법에서 정한 의료기관에서 의사의 관리 하에 기구를 사용하여 생체(生體)에 절단(切斷, 특정부위를 잘라 내는 것), 절제(切除, 특정부위를 잘라 없애는 것) 등의 조작을 가하는 것을 말합니다.\n② 보건복지부 산하 신의료기술평가위원회로부터 안전성과 유효성을 인정받은 최신 신의료기술 수술(예: 하이푸, 감마나이프, 전립선결찰술, 레이저 정맥폐쇄술 등)도 절단·절제에 준하는 수술로 인정하여 지급합니다.\n③ 단, 동일한 질병을 직접적인 목적으로 2회 이상의 질병수술을 받은 경우에는 1회의 수술급여금만 지급합니다. (단, 365일 경과 후 재수술 시 재지급)",
